/* atlas.js — #684 THE ATLAS: the drawn maps of a campaign, generated by the TnD Maps library (tndmaps.js).
   "The map" already means the location graph (memory.map), so the drawn maps are the atlas. Design: DOC/DESIGN_684_atlas.md.

   worldState.atlas = {v, seed, at, spot, off, ptr, zones, names}
     seed     the campaign's map seed — also the id of the root zone, the region
     zones    {<zoneId>: {kind, parent, via, params, name, lib, fp, turn, redrawn?}} — RECIPES, never documents. A zone's
              document is a pure function of its recipe chain; a region document is 303 KB and a city 134 KB, a recipe is
              bytes. A zone id is the seed the library derives for that zone (<seed>/p0, <seed>/p0/inn-1, <seed>/p0/sewer):
              unique by construction, the same from every way in. kind = the generator; via = what the parent's nesting
              function takes (a portal id; a wild zone's own id); params = authored params only — the root keeps its
              RESOLVED params, so a changed library default cannot redraw a running campaign's realm.
     at/spot  where the party stands: a zone id, and the id of a thing in it (null = somewhere in that zone). at null = the
              party has no place on the map yet.
     off      {name, why, within?} while the story's current place has no place on the map; at/spot keep the last mapped one
     ptr      the location pointer last followed (following is idempotent)
     names    {<location key>: {zone, id}} — the PLAYER's ties only (atlasPlace): a story place the player put on the map.
              A name the story uses is never kept: it is looked up afresh each time, where the party stands.

   THE RULE: the engine never guesses a tie. A story place is on the map when its name IS a map name (exact once case, a
   leading "the" and punctuation are folded, and only when one thing bears it) ON A SHEET THE PARTY STANDS ON — its own
   sheet first, then the sheets above it, never a sheet beside or beneath it: the Common Room of the inn the party left
   is not the Common Room of the inn it is in, and another town's Black Cup is not this town's — or when the player
   said so (atlasPlace — the pane's "We are here"). Anything else is off the map, said plainly; a guessed tie would be
   served to the GM as canon.

   Reads (atlasDoc, atlasThings, atlasPartyIn, atlasMarkers, atlasZones, atlasWhere, atlasCard, atlasReveal, atlasMapBlock) never write the campaign. The writers are
   atlasCreate, atlasFollow, atlasPlace and atlasHeal; a redraw a read notices is recorded by the next writer. */
var ATLAS_VER=1;
/* documents held in memory at once: the least recently used is dropped and redrawn on demand (a region is ~300 KB) */
var ATLAS_DOC_CAP=12;

/* THE NESTING TABLE — "<parent generator>><child generator>": how the child's params come from the parent's document.
   via "id" = the portal's own id; "to" = the id the portal points at (a wild zone is named by its zone id). point = where
   the child sits on the parent's sheet when no thing of the parent bears the via. A new scale is a new entry. */
var ATLAS_BUILDERS={
  "region>town":{via:"id",make:function(doc,via){return TnDMaps.town.fromRegion(doc,via);}},
  "region>dungeon":{via:"id",make:function(doc,via){return TnDMaps.dungeon.fromRegion(doc,via);}},
  "region>wild":{via:"to",make:function(doc,via){return TnDMaps.wild.fromRegion(doc,via);},point:function(doc,via){var z=TnDMaps.wild.zoneAt(doc,via);return [z.cx,z.cy];}},
  "town>dungeon":{via:"id",make:function(doc,via){return TnDMaps.dungeon.fromTown(doc,via);}},
  "town>interior":{via:"id",make:function(doc,via){return TnDMaps.interior.fromTown(doc,via);}},
  "dungeon>dungeon":{via:"id",make:function(doc,via){return TnDMaps.dungeon.fromDungeon(doc,via);}},
  "interior>dungeon":{via:"id",make:function(doc,via){return TnDMaps.dungeon.fromInterior(doc,via);}}
};
/* the NAMED THINGS of a document, per generator, beside its portals (which every document carries) */
var ATLAS_THINGS={
  region:function(d){return [].concat(d.places||[],d.caves||[],d.features||[]);},
  town:function(d){return [].concat(d.establishments||[],d.landmarks||[]);},
  dungeon:function(d){return d.rooms||[];},
  interior:function(d){return d.rooms||[];},
  wild:function(d){return d.features||[];}
};
/* a portal of one of these ways leads back to the zone this one hangs from */
var ATLAS_WAYS_BACK={up:1,out:1};
/* v → the function lifting a store to v+1 (none yet: v1 is the first shape) */
var ATLAS_MIGRATIONS={};

var _atlasDocs={},_atlasDocOrder=[],_atlasDrawn={},_atlasWarned={};

function atlasSay(level,msg){
  if(typeof console!=="undefined")(console[level]||console.log).call(console,"[atlas] "+msg);
  if(level!=="info"&&typeof showToast==="function")showToast("Map: "+msg,6000);
}
/* an exception the atlas did not expect: loud, attributable, and never allowed out of a writer (a turn must still commit) */
function atlasProblem(where,e){
  var msg=(e&&e.message)?e.message:String(e);
  atlasSay("warn",where+" failed — "+msg);
  if(typeof reportError==="function"&&!atlasIsRefusal(e))reportError("atlas "+where,msg,(e&&e.stack)?String(e.stack).slice(0,600):"");
  return msg;
}
/* the library refuses in words ("TnDMaps: that point lies in the sea — {data}"): a refusal is an answer, not a bug */
function atlasIsRefusal(e){return /^TnDMaps: /.test((e&&e.message)?e.message:String(e));}
function atlasReason(e){return String((e&&e.message)?e.message:e).replace(/^TnDMaps: /,"").replace(/ — \{[\s\S]*$/,"");}
function atlasTurn(){return (typeof worldState!=="undefined"&&worldState&&typeof worldState.turn==="number")?worldState.turn:0;}
/* say a thing once per campaign per session (the latches must not carry one campaign's silence into the next) */
function atlasOnce(A,what){var k=String((A&&A.seed)||"")+"\n"+what;if(_atlasWarned[k])return false;_atlasWarned[k]=1;return true;}
/* the store, when this build can use it; a store from a newer build is left alone, said once */
function atlasLive(){
  var A=(typeof worldState!=="undefined"&&worldState)?worldState.atlas:null;
  if(!A)return null;
  if(A.v!==ATLAS_VER){if(atlasOnce(A,"ver")){atlasSay("warn","this campaign's map was saved by a newer version of the game (atlas v"+A.v+", this build reads v"+ATLAS_VER+") — it is left untouched");}return null;}
  return A;
}
function atlasHas(){return !!atlasLive();}
function atlasSeedMint(){
  var a="abcdefghijklmnopqrstuvwxyz0123456789",s="",i,r;
  if(typeof crypto!=="undefined"&&crypto&&crypto.getRandomValues){r=new Uint8Array(12);crypto.getRandomValues(r);for(i=0;i<12;i++)s+=a.charAt(r[i]%36);}
  else for(i=0;i<12;i++)s+=a.charAt(Math.floor(Math.random()*36));
  return s;
}
/* what the library drew, as one short string: the document without its timings (stats) and without the caches the
   library hangs on a document it has read (keys starting "_") — both differ between two draws of the same map */
function atlasFingerprint(doc){
  var s=JSON.stringify(doc,function(k,v){return (this===doc&&(k==="stats"||k.charAt(0)==="_"))?undefined:v;});
  return (TnDMaps.hash32(s)>>>0).toString(16)+"-"+s.length.toString(36);
}
function atlasNameKey(s){
  return String(s==null?"":s).toLowerCase().replace(/[‘’]/g,"'").replace(/[\s.,;:!?\-–—_"()\[\]]+/g," ").replace(/^ +| +$/g,"").replace(/^the /,"");
}

/* ── documents ─────────────────────────────────────────────────────────────────────────────────────────────── */
function atlasRecipe(A,zoneId){var rec=A.zones[zoneId];if(!rec)throw new Error("atlas: no zone '"+zoneId+"' in this campaign's atlas");return rec;}
/* a document is keyed by its whole recipe chain, so an authored change anywhere above can never serve a stale drawing */
function atlasChainKey(A,zoneId){
  var parts=[],z=zoneId,rec,guard=0;
  while(z){if(guard++>64)throw new Error("atlas: the zone chain above '"+zoneId+"' loops");rec=atlasRecipe(A,z);parts.push(z+"|"+rec.kind+"|"+(rec.via==null?"":rec.via)+"|"+(rec.params?JSON.stringify(rec.params):""));z=rec.parent;}
  return parts.join("\n");
}
function atlasZoneParams(A,zoneId){
  var rec=atlasRecipe(A,zoneId),params,b;
  if(!rec.parent)params=JSON.parse(JSON.stringify(rec.params));
  else{
    b=ATLAS_BUILDERS[atlasRecipe(A,rec.parent).kind+">"+rec.kind];
    if(!b)throw new Error("atlas: nothing builds a "+rec.kind+" from a "+atlasRecipe(A,rec.parent).kind+" (zone '"+zoneId+"')");
    params=b.make(atlasDoc(rec.parent),rec.via);
    if(rec.params)params=Object.assign({},params,JSON.parse(JSON.stringify(rec.params)));
  }
  if(!params||params.seed!==zoneId)throw new Error("atlas: zone '"+zoneId+"' now derives the seed '"+(params&&params.seed)+"' — the library names its zones differently than when this campaign was mapped");
  return params;
}
function atlasDoc(zoneId){
  var A=atlasLive();if(!A)throw new Error("atlas: this campaign has no atlas");
  var key=atlasChainKey(A,zoneId),doc=_atlasDocs[key],at;
  if(!doc){
    doc=TnDMaps.generate(atlasRecipe(A,zoneId).kind,atlasZoneParams(A,zoneId));
    _atlasDocs[key]=doc;_atlasDrawn[key]={fp:atlasFingerprint(doc),lib:TnDMaps.VERSION,name:(doc.title&&doc.title.name)||null};
  }else{at=_atlasDocOrder.indexOf(key);if(at>=0)_atlasDocOrder.splice(at,1);}
  _atlasDocOrder.push(key);
  while(_atlasDocOrder.length>ATLAS_DOC_CAP){at=_atlasDocOrder.shift();delete _atlasDocs[at];delete _atlasDrawn[at];}
  return doc;
}
/* drop every held document (a campaign switch, a test): the next read redraws from the recipes */
function atlasForget(){_atlasDocs={};_atlasDocOrder=[];_atlasDrawn={};_atlasWarned={};}
/* WRITE: record what the library drew for a zone; a drawing that differs from the one on record is said out loud */
function atlasSettle(A,zoneId){
  var rec=A.zones[zoneId],d=rec?_atlasDrawn[atlasChainKey(A,zoneId)]:null;
  if(!d)return null;
  if(d.name&&rec.name!==d.name)rec.name=d.name;
  if(!rec.fp){rec.fp=d.fp;rec.lib=d.lib;return null;}
  if(rec.fp===d.fp){if(rec.lib!==d.lib)rec.lib=d.lib;return null;}
  rec.redrawn={from:rec.lib,to:d.lib,was:rec.fp,turn:atlasTurn()};rec.fp=d.fp;rec.lib=d.lib;
  atlasSay("warn","the map of "+(rec.name||zoneId)+" was redrawn"+(rec.redrawn.from!==rec.redrawn.to?" by a newer map library ("+rec.redrawn.from+" → "+rec.redrawn.to+")":" differently from its record")+" — places the story already used there may have moved");
  return rec.redrawn;
}
function atlasSettleChain(A,zoneId){var z=zoneId,guard=0;while(z&&A.zones[z]&&guard++<64){atlasSettle(A,z);z=A.zones[z].parent;}}

/* ── things: what on a sheet has a name ────────────────────────────────────────────────────────────────────── */
function atlasThings(doc){
  var kind=doc.generator&&doc.generator.name,list=ATLAS_THINGS[kind]?ATLAS_THINGS[kind](doc):[],out=[],byId={},i,j,keep;
  function add(o,portal){
    if(!o||o.id==null||typeof o.name!=="string"||!o.name||!isFinite(o.x)||!isFinite(o.y))return;
    if(byId[o.id]){if(portal&&!byId[o.id].portal)byId[o.id].portal=portal;return;}
    byId[o.id]={id:o.id,name:o.name,x:o.x,y:o.y,kind:o.kind||null,word:o.word||null,portal:portal||null};out.push(byId[o.id]);
  }
  for(i=0;i<(doc.portals||[]).length;i++)add(doc.portals[i],doc.portals[i]);
  for(i=0;i<list.length;i++)add(list[i],null);
  /* one place under two ids (a town's outfall is a landmark and a way down at one point): the way in is the thing */
  keep=out.filter(function(t){
    if(t.portal)return true;
    for(j=0;j<out.length;j++)if(out[j].portal&&atlasNameKey(out[j].name)===atlasNameKey(t.name)&&Math.abs(out[j].x-t.x)<=2&&Math.abs(out[j].y-t.y)<=2)return false;
    return true;
  });
  return keep;
}
function atlasThingById(doc,id){var t=atlasThings(doc),i;for(i=0;i<t.length;i++)if(t[i].id===id)return t[i];return null;}
/* a name on one sheet: {thing} when exactly one thing bears it, {many: n} when several do, {title: true} for the sheet's own name */
function atlasFind(doc,name){
  var key=atlasNameKey(name),hits;
  if(!key)return null;
  hits=atlasThings(doc).filter(function(t){return atlasNameKey(t.name)===key;});
  if(hits.length===1)return {thing:hits[0]};
  if(hits.length>1)return {many:hits.length};
  if(doc.title&&atlasNameKey(doc.title.name)===key)return {title:true};
  return null;
}
function atlasCentre(doc){
  var c=doc.centre;
  if(c&&isFinite(c[0])&&isFinite(c[1]))return [c[0],c[1]];
  return [doc.frame.width/2,doc.frame.height/2];
}

/* ── moving between zones ──────────────────────────────────────────────────────────────────────────────────── */
/* where a way in comes out on the far side. from = {id}: the thing with the same id (a grate is the same grate above
   and below), else the ONE portal that points back at it — a town has several roads onto its place and a house two
   doors, and which one the party used is not on record. from = {to}: the ONE portal that points back at that zone (a
   wild zone's own north edge is not where a party walking north comes in). */
function atlasWayIn(doc,from){
  var i,p,back=[],target;
  if(!from)return null;
  if(from.id!=null&&atlasThingById(doc,from.id))return from.id;
  target=from.id!=null?from.id:from.to;
  if(target==null)return null;
  for(i=0;i<(doc.portals||[]).length;i++){p=doc.portals[i];if(p.to&&p.to.id===target)back.push(p.id);}
  return back.length===1?back[0]:null;
}
/* WRITE: the zone a builder makes from parentZone — its recipe is filed the first time, then it is the same zone from every way in */
function atlasOpen(A,parentZone,kind,via,from,entered){
  var b=ATLAS_BUILDERS[atlasRecipe(A,parentZone).kind+">"+kind],params=b.make(atlasDoc(parentZone),via),id=params&&params.seed,fresh=false,doc;
  if(typeof id!=="string"||!id)throw new Error("atlas: the library derived no seed for a "+kind+" through '"+via+"'");
  if(!A.zones[id]){A.zones[id]={kind:kind,parent:parentZone,via:via,params:null,name:null,lib:null,fp:null,turn:atlasTurn()};fresh=true;}
  try{doc=atlasDoc(id);}catch(e){if(fresh)delete A.zones[id];throw e;}
  if(fresh){atlasSettle(A,id);if(entered)entered.push(id);atlasSay("info","drew "+(A.zones[id].name||id)+" ("+kind+")");}
  return {zone:id,spot:atlasWayIn(doc,from)};
}
/* where a portal leads, WITHOUT opening anything: {back: zoneId} for a way back up, {parent, kind, via} for a zone a
   builder makes, null for a way that leads nowhere (the edge of the realm) */
function atlasPortalRoute(A,zoneId,portal){
  var G=portal.to&&portal.to.generator,z,b,via;
  if(!G)return null;
  if(ATLAS_WAYS_BACK[portal.way]){z=atlasRecipe(A,zoneId).parent;return z?{back:z}:null;}
  /* the nearest zone, from here upward, that can build a G: a wild zone's ways lead to zones that hang from the region */
  for(z=zoneId;z;z=atlasRecipe(A,z).parent){
    b=ATLAS_BUILDERS[atlasRecipe(A,z).kind+">"+G];
    if(b){via=(b.via==="to")?portal.to.id:portal.id;return via==null?null:{parent:z,kind:G,via:via,far:b.via==="to"};}
  }
  /* nothing builds one: it is a way back up to the zone of that kind (a town's road onto the region) */
  for(z=atlasRecipe(A,zoneId).parent;z;z=atlasRecipe(A,z).parent)if(atlasRecipe(A,z).kind===G)return {back:z};
  return null;
}
/* WRITE: the zone a portal leads to, opened if it is new; null when it leads nowhere */
function atlasPortalTarget(A,zoneId,portal,entered){
  var r=atlasPortalRoute(A,zoneId,portal);
  if(!r)return null;
  if(r.back)return {zone:r.back,spot:atlasWayIn(atlasDoc(r.back),{id:portal.to.id})};
  /* a zone the far side names (a wild zone's edge) is entered where ITS way points back at the zone the party left */
  return atlasOpen(A,r.parent,r.kind,r.via,r.far?{to:atlasRecipe(A,zoneId).via}:{id:portal.id},entered);
}
/* standing at a thing: a way in is entered, anything else is a spot on its own sheet */
function atlasArrive(A,zone,id,entered){
  var t,target;
  if(id==null)return {zone:zone,spot:null};
  t=atlasThingById(atlasDoc(zone),id);
  if(!t)throw new Error("atlas: '"+id+"' is not on the map of "+(atlasRecipe(A,zone).name||zone)+" any more");
  if(t.portal&&!ATLAS_WAYS_BACK[t.portal.way]){target=atlasPortalTarget(A,zone,t.portal,entered);if(target)return target;}
  return {zone:zone,spot:id};
}

/* ── the location pointer ──────────────────────────────────────────────────────────────────────────────────── */
function atlasPointer(){var w=(typeof worldState!=="undefined"&&worldState)?worldState.world:null;return (w&&w.location)?{world:String(w.location),sub:w.sublocation?String(w.sublocation):null}:null;}
function atlasLocKey(k){return (typeof locResolve==="function")?locResolve(k):k;}
function atlasWorldKey(p){return atlasLocKey(p.world);}
function atlasSubKey(p){return p.sub?atlasLocKey(atlasWorldKey(p)+"|"+p.sub):null;}
/* the player's tie for a location key — read through the identity layer, so a place that was merged keeps its tie */
function atlasTie(A,key){
  var t=A.names[key],ks,i;
  if(!t){ks=Object.keys(A.names);for(i=0;i<ks.length;i++)if(atlasLocKey(ks[i])===key){t=A.names[ks[i]];break;}}
  return (t&&A.zones[t.zone])?{zone:t.zone,id:t.id==null?null:t.id}:null;
}
/* the sheets from one zone upward, nearest first, as far as stopAt (null = the region) */
function atlasChainUp(A,zoneId,stopAt){
  var out=[],z=zoneId,guard=0;
  while(z&&A.zones[z]&&guard++<64){out.push(z);if(z===stopAt)break;z=A.zones[z].parent;}
  return out;
}
/* a story name → {hit: {zone, id}} or {hit: null, why}. The player's tie wins. Otherwise the name is looked up on the
   given sheets, nearest first; the first sheet that bears it decides, and it must bear it exactly once — two bearers is
   a refusal, never a pick. A match is NEVER recorded: the same words name another place from another spot. */
function atlasResolve(A,key,name,sheets){
  var tie=atlasTie(A,key),i,m;
  if(tie)return {hit:tie};
  for(i=0;i<sheets.length;i++){
    m=atlasFind(atlasDoc(sheets[i]),name);
    if(!m)continue;
    if(m.many)return {hit:null,why:m.many+" places on the map of "+(A.zones[sheets[i]].name||sheets[i])+" are called that"};
    return {hit:{zone:sheets[i],id:m.thing?m.thing.id:null}};
  }
  return {hit:null,why:"no place on the map has that name"};
}
/* WRITE: follow the story's location pointer. Idempotent; never throws (it runs inside a turn's commit). Returns
   {changed, at, spot, off, entered} or null when the campaign has no atlas. */
function atlasFollow(){
  var A=atlasLive(),p=A?atlasPointer():null,sig,before,entered=[],w,s,prev,home,sheets;
  if(!A||!p)return null;
  sig=JSON.stringify([p.world,p.sub]);
  if(A.ptr===sig){try{atlasSettleChain(A,A.at);}catch(e0){atlasProblem("settling",e0);}return {changed:false,at:A.at,spot:A.spot,off:A.off,entered:entered};}
  before=JSON.stringify([A.at,A.spot,A.off]);
  try{
    prev=(A.at&&A.zones[A.at])?A.at:null;
    /* a world name: from the sheet the party stands on, upward to the region */
    w=atlasResolve(A,atlasWorldKey(p),p.world,atlasChainUp(A,prev||A.seed,null));
    if(!w.hit)A.off={name:p.world,why:w.why};
    else{
      atlasStand(A,atlasArrive(A,w.hit.zone,w.hit.id,entered));A.off=null;
      if(p.sub){
        /* a sub-location: on the sheet the world place led to — and, when the party already stood on a sheet beneath
           it, from that sheet upward first. Never on a sheet the party is not inside. */
        home=A.at;
        sheets=(prev&&prev!==home&&atlasChainUp(A,prev,null).indexOf(home)>=0)?atlasChainUp(A,prev,home):[home];
        s=atlasResolve(A,atlasSubKey(p),p.sub,sheets);
        if(s.hit)atlasStand(A,atlasArrive(A,s.hit.zone,s.hit.id,entered));
        else A.off={name:p.sub,why:s.why,within:home};
      }
    }
    atlasSettleChain(A,A.at);
  }catch(e){A.off={name:p.sub||p.world,why:"the map could not follow the story there ("+atlasProblem("following the party",e)+")"};}
  A.ptr=sig;
  return {changed:before!==JSON.stringify([A.at,A.spot,A.off]),at:A.at,spot:A.spot,off:A.off,entered:entered};
}
function atlasStand(A,where){A.at=where.zone;A.spot=where.spot==null?null:where.spot;}

/* WRITE: start a campaign's atlas — the region is drawn now, the party is not on it yet. Throws on a second call. */
function atlasCreate(seed){
  var A,doc;
  if(typeof worldState==="undefined"||!worldState)throw new Error("atlas: no campaign is loaded");
  if(worldState.atlas)throw new Error("atlas: this campaign already has an atlas");
  if(seed==null)seed=atlasSeedMint();
  if(typeof seed!=="string"||!/^[A-Za-z0-9-]{4,40}$/.test(seed))throw new Error("atlas: a map seed is 4–40 letters, digits or hyphens");
  doc=TnDMaps.generate("region",{seed:seed});
  A={v:ATLAS_VER,seed:seed,at:null,spot:null,off:null,ptr:null,zones:keyedDict(),names:keyedDict()};
  A.zones[seed]={kind:"region",parent:null,via:null,params:JSON.parse(JSON.stringify(doc.params)),name:(doc.title&&doc.title.name)||null,lib:TnDMaps.VERSION,fp:atlasFingerprint(doc),turn:atlasTurn()};
  worldState.atlas=A;
  atlasSay("info","drew "+A.zones[seed].name+" (region) from the seed "+seed);
  return A;
}

/* WRITE: "We are here" — the player ties the story's current place to a thing on a sheet ({id}), or to open ground on
   the region ({x, y}: the wild zone at that point). The ONLY writer of a tie. What is tied is atlasPlacePreview()'s
   answer: the WORLD place while it is off the map (a tavern cannot stand in a town the map does not know), else the
   sub-location when the story names one. expect = the {level, name} the player was shown: when the story has moved on
   since (a turn landed under an open card) the tap is refused, never spent on another place.
   Returns {ok: true, at, spot, off, entered, bound, level} or {ok: false, reason, moved?}; a refusal changes nothing
   but zones the tap had to draw to look. */
function atlasPlace(zoneId,target,expect){
  var A=atlasLive(),p=A?atlasPointer():null,entered=[],rec,doc,tie,b,z,r,pv;
  if(!A)return {ok:false,reason:"this campaign has no map"};
  if(!p)return {ok:false,reason:"the story has no current place"};
  if(!A.zones[zoneId])return {ok:false,reason:"that sheet is not in this campaign's atlas"};
  atlasFollow();/* what a tap ties is read from where the story stands NOW */
  pv=atlasPlacePreview();
  if(expect&&(expect.level!==pv.level||expect.name!==pv.name))return {ok:false,moved:true,reason:"the story has moved on \u2014 the place to put on the map is now "+pv.name};
  try{
    rec=A.zones[zoneId];doc=atlasDoc(zoneId);
    if(target&&target.id!=null){
      if(!atlasThingById(doc,target.id))return {ok:false,reason:"nothing on that sheet has the id '"+target.id+"'"};
      tie={zone:zoneId,id:target.id};atlasArrive(A,zoneId,target.id,entered);
    }else if(target&&isFinite(target.x)&&isFinite(target.y)){
      b=ATLAS_BUILDERS[rec.kind+">wild"];
      if(!b)return {ok:false,reason:"only the region has open country to stand in \u2014 pick a place on this sheet"};
      z=TnDMaps.wild.zoneAt(doc,[target.x,target.y]);
      tie={zone:atlasOpen(A,zoneId,"wild",z.id,null,entered).zone,id:null};
    }else return {ok:false,reason:"pick a place or a point on the sheet"};
  }catch(e){
    if(!atlasIsRefusal(e))atlasProblem("placing the party",e);
    return {ok:false,reason:atlasReason(e)};
  }
  A.names[pv.level==="sub"?atlasSubKey(p):atlasWorldKey(p)]=tie;A.ptr=null;
  r=atlasFollow();
  return {ok:true,at:A.at,spot:A.spot,off:A.off,entered:entered.concat((r&&r.entered)||[]),bound:pv.name,level:pv.level};
}

/* ── reads for the pane and the prompt ─────────────────────────────────────────────────────────────────────── */
/* the things on a sheet through which a zone hanging from it is entered: where the child's ways back come out */
function atlasWaysInto(A,zoneId,childId){
  var doc=atlasDoc(zoneId),ps=atlasDoc(childId).portals||[],ids=[],i,p;
  for(i=0;i<ps.length;i++){p=ps[i];if(ATLAS_WAYS_BACK[p.way]&&p.to&&p.to.id!=null&&ids.indexOf(p.to.id)<0&&atlasThingById(doc,p.to.id))ids.push(p.to.id);}
  return ids;
}
/* where the party shows on a zone's sheet: on its own sheet at its spot; on a sheet above, at the way down to it.
   {x, y, exact, last, within}. exact false = the party is in that zone but the map does not know where (a town entered
   by name; a sewer with three grates and the party somewhere inside). last true = the story has LEFT the mapped
   places: this is the last mapped place, never "the party is here". null = not on that sheet. */
function atlasPartyIn(zoneId){
  var A=atlasLive(),doc,t,z,rec,b,c,ways,ps,i,guard=0,last,mk;
  if(!A||!A.at||!A.zones[zoneId]||!A.zones[A.at])return null;
  last=!!(A.off&&!A.off.within);
  mk=function(x,y,exact,within){return {x:x,y:y,exact:exact&&!last,last:last,within:within};};
  doc=atlasDoc(zoneId);
  if(A.at===zoneId){t=A.spot!=null?atlasThingById(doc,A.spot):null;if(t)return mk(t.x,t.y,true,null);c=atlasCentre(doc);return mk(c[0],c[1],false,null);}
  for(z=A.at;z&&A.zones[z]&&guard++<64;z=A.zones[z].parent){
    rec=A.zones[z];
    if(rec.parent!==zoneId)continue;
    /* a child no thing of this sheet leads into (a wild zone) sits where its builder says */
    b=ATLAS_BUILDERS[A.zones[zoneId].kind+">"+rec.kind];
    if(b&&b.point&&!atlasThingById(doc,rec.via)){c=b.point(doc,rec.via);return mk(c[0],c[1],true,z);}
    /* the party stands AT one of the child's ways back: that way's thing on this sheet */
    if(z===A.at&&A.spot!=null){ps=atlasDoc(z).portals||[];for(i=0;i<ps.length;i++)if(ps[i].id===A.spot&&ATLAS_WAYS_BACK[ps[i].way]&&ps[i].to){t=atlasThingById(doc,ps[i].to.id);if(t)return mk(t.x,t.y,true,z);}}
    /* one way in (a house's door, a cave's mouth), or a child that names no way back (a town sits on its place) */
    ways=atlasWaysInto(A,zoneId,z);
    if(ways.length<=1){t=atlasThingById(doc,ways.length?ways[0]:rec.via);if(t)return mk(t.x,t.y,true,z);}
    /* several ways in and the party somewhere inside: the sheet does not know under which — never the first one used */
    c=atlasCentre(doc);return mk(c[0],c[1],false,z);
  }
  return null;
}
/* READ: the named thing standing at a point of a sheet (a marker is drawn exactly on the thing it stands on) */
function atlasThingAt(zoneId,x,y){
  var A=atlasLive(),t,i;
  if(!A||!A.zones[zoneId]||!isFinite(x)||!isFinite(y))return null;
  t=atlasThings(atlasDoc(zoneId));
  for(i=0;i<t.length;i++)if(Math.abs(t[i].x-x)<=0.5&&Math.abs(t[i].y-y)<=0.5)return t[i];
  return null;
}
/* the markers TnDMaps.markers / view.setMarkers take for a sheet — derived from the store, never stored */
function atlasMarkers(zoneId){var p=atlasPartyIn(zoneId);return p?[{id:"party",kind:"party",x:p.x,y:p.y,label:p.last?"Last mapped place":(p.exact?"The party":"The party (somewhere here)")}]:[];}
/* the entered zones, root first then in order of entry */
function atlasZones(){
  var A=atlasLive();if(!A)return [];
  return Object.keys(A.zones).map(function(id){var r=A.zones[id];return {id:id,kind:r.kind,name:r.name||id,parent:r.parent,turn:r.turn,redrawn:r.redrawn||null};});
}
/* the chain of zones from the region down to one zone */
function atlasTrail(zoneId){var A=atlasLive(),out=[],z=zoneId,guard=0;if(!A)return out;while(z&&A.zones[z]&&guard++<64){out.unshift(z);z=A.zones[z].parent;}return out;}

/* ── what the pane and the prompt say ──────────────────────────────────────────────────────────────────────── */
/* READ: the id of the zone a portal leads to, entered or not; null when it leads nowhere */
function atlasPortalPeek(A,zoneId,portal){
  var r=atlasPortalRoute(A,zoneId,portal),params;
  if(!r)return null;
  if(r.back)return r.back;
  params=ATLAS_BUILDERS[atlasRecipe(A,r.parent).kind+">"+r.kind].make(atlasDoc(r.parent),r.via);
  return (params&&typeof params.seed==="string")?params.seed:null;
}
/* how a spot is said, by the thing's kind (default: "at <name>") */
var ATLAS_SPOT_PHRASE={edge:function(t){return "at its edge, "+t.name;}};
/* READ: where the party is, in words and in parts — the pane's status line and the first line the GM is told */
function atlasWhere(){
  var A=atlasLive(),rec,t,out,why,phrase="";
  if(!A)return null;
  out={placed:!!(A.at&&A.zones[A.at]),zone:null,zoneName:null,zoneKind:null,spot:null,spotName:null,off:A.off||null,text:""};
  why=A.off?"\""+A.off.name+"\" is not on "+(A.off.within?"its map":"the map")+" ("+A.off.why+")":"";
  if(!out.placed){out.text="The party is not on the map yet."+(why?" "+why+".":"");return out;}
  rec=A.zones[A.at];out.zone=A.at;out.zoneName=rec.name||A.at;out.zoneKind=rec.kind;
  if(A.spot!=null){t=atlasThingById(atlasDoc(A.at),A.spot);if(t){out.spot=t.id;out.spotName=t.name;if(atlasNameKey(t.name)!==atlasNameKey(out.zoneName))phrase=", "+(ATLAS_SPOT_PHRASE[t.kind]?ATLAS_SPOT_PHRASE[t.kind](t):"at "+t.name);}}
  if(A.off&&!A.off.within)out.text=why+". The party's last mapped place is "+out.zoneName+".";
  else out.text="The party is in "+out.zoneName+phrase+"."+(why?" "+why+".":"");
  return out;
}
/* READ: what a "We are here" tap would tie. The world place first: while it is off the map (or the party is nowhere, or
   the atlas has not followed the pointer) a tap places IT; once the world place is on the map — by its own name or by a
   tie — a tap places the sub-location, when the story names one. */
function atlasPlacePreview(){
  var A=atlasLive(),p=A?atlasPointer():null,worldOff;
  if(!A||!p)return null;
  worldOff=!A.at||!A.zones[A.at]||A.ptr!==JSON.stringify([p.world,p.sub])||!!(A.off&&!A.off.within);
  return (p.sub&&!worldOff)?{level:"sub",name:p.sub}:{level:"world",name:p.world};
}
/* what the PLAYER may see of a sheet, per generator: the ids drawn (the library's fog of war), absent = everything.
   A dungeon shows its ways up — they are known from the sheet above — and the chamber the party stands in; the rest
   waits for the game to track rooms. */
var ATLAS_REVEAL={
  dungeon:function(doc,spot){
    var up={},ids=[];
    (doc.portals||[]).forEach(function(p){if(ATLAS_WAYS_BACK[p.way])up[p.id]=1;});
    (doc.rooms||[]).forEach(function(r){if(up[r.id]||(r.portal&&up[r.portal])||r.id===spot)ids.push(r.id);});
    return ids;
  }
};
/* READ: the reveal list view.setReveal takes for a sheet; null = the whole sheet */
function atlasReveal(zoneId){
  var A=atlasLive(),rec=A?A.zones[zoneId]:null,f=rec?ATLAS_REVEAL[rec.kind]:null;
  return f?f(atlasDoc(zoneId),A.at===zoneId?A.spot:null):null;
}
/* READ: the card for a tapped thing ({id}) or a tapped point of open ground ({x, y}; the region only):
   {id, x, y, title, word, opens, unvisited, partyHere, place}. opens = the entered zone it leads to (the pane may show
   it); unvisited = it leads to a zone the party has not entered (never shown: no peeking). null = nothing to say. */
function atlasCard(zoneId,target){
  var A=atlasLive(),rec=A?A.zones[zoneId]:null,doc,t,leads=null,z,trail,b,gone;
  if(!rec||!target)return null;
  doc=atlasDoc(zoneId);trail=A.at?atlasTrail(A.at):[];
  gone=!!(A.off&&!A.off.within);/* the story has left the mapped places: nothing is "where the party is", and every card offers We are here */
  if(target.id!=null){
    t=atlasThingById(doc,target.id);if(!t)return null;
    if(t.portal){try{leads=atlasPortalPeek(A,zoneId,t.portal);}catch(e){leads=null;}}
    return {id:t.id,x:t.x,y:t.y,title:t.name,word:t.word||t.kind||"",opens:(leads&&A.zones[leads]&&leads!==zoneId)?leads:null,unvisited:!!(leads&&!A.zones[leads]),
      partyHere:!gone&&((A.at===zoneId&&A.spot===t.id)||!!(leads&&leads!==zoneId&&trail.indexOf(leads)>=0&&trail.indexOf(leads)>trail.indexOf(zoneId))),place:atlasPlacePreview()};
  }
  b=ATLAS_BUILDERS[rec.kind+">wild"];
  if(!b||!isFinite(target.x)||!isFinite(target.y))return null;
  try{z=TnDMaps.wild.zoneAt(doc,[target.x,target.y]);leads=b.make(doc,z.id).seed;}
  catch(e2){return {id:null,x:target.x,y:target.y,title:"Open country",word:"",opens:null,unvisited:false,partyHere:false,place:null,refused:atlasReason(e2)};}
  return {id:null,x:target.x,y:target.y,title:"Open country",word:"",opens:A.zones[leads]?leads:null,unvisited:false,partyHere:!gone&&A.at===leads,place:atlasPlacePreview()};
}

/* ── the MAP block: what the GM is told the map says ───────────────────────────────────────────────────────── */
/* The block rides the VOLATILE half of the prompt, right after GEOGRAPHY (buildSysPrompt) — never inside buildGeoBlock,
   which Table Talk reuses: a dungeon's digest names every chamber, and the help desk must not hand the player a sheet
   the pane keeps fogged. "" without an atlas, so every other campaign's prompt is byte-identical. A pure read.
   The sheet text is the library's own digest; the cap cuts it at a sentence end and SAYS so; the where-line and the
   naming rule are never cut. */
var ATLAS_BRIEF_CAP=3600;/* characters of sheet text: a city's digest is ~2,500 and its trades are what sub-locations bind to */
var ATLAS_BRIEF_HEAD="MAP (the drawn map of this world — canon for where places are, how far apart they lie and what stands in them; where it and a description above disagree about layout, distance or direction, the map is right):";
var ATLAS_BRIEF_RULE="Names on this map are exact. When the party goes to a place it names, use that exact name: [LOCATION:] for a settlement, a cave or a stretch of country, [SUBLOCATION:] for a building, a way down or a chamber. A place you invent is not on the map and stays off it until the player places it.";
var ATLAS_BRIEF_CUT=" […the rest of this sheet is not shown here]";
function atlasDigestText(zoneId){
  var A=atlasLive(),doc=atlasDoc(zoneId),d=_atlasDrawn[atlasChainKey(A,zoneId)];
  if(d&&typeof d.digest==="string")return d.digest;
  var text=String(TnDMaps.digest(doc).text||"");
  if(d)d.digest=text;
  return text;
}
/* the realm in brief: the digest's opening paragraph (seas, ranges, forests, rivers, caves) and every settlement by name */
function atlasRegionBrief(A){
  var text=atlasDigestText(A.seed),cut=text.indexOf("\n\n"),doc=atlasDoc(A.seed);
  return (cut<0?text:text.slice(0,cut))+"\nSettlements: "+(doc.places||[]).map(function(p){return p.name+" ("+p.kind+")";}).join(", ")+".";
}
/* a settlement's own paragraph of the region digest: its site and its neighbours with bearing, distance and days */
function atlasRegionLine(A,placeId){
  var doc=atlasDoc(A.seed),place=null,lines,i;
  (doc.places||[]).forEach(function(p){if(p.id===placeId)place=p;});
  if(!place)return "";
  lines=atlasDigestText(A.seed).split("\n");
  for(i=0;i<lines.length;i++)if(lines[i].indexOf(place.name+" is ")===0)return lines[i];
  return "";
}
/* the sheet text for a zone, per generator: its digest, plus what only the sheet above knows */
var ATLAS_BRIEF={
  region:function(A){return atlasRegionBrief(A);},
  town:function(A,zoneId){var near=atlasRegionLine(A,A.zones[zoneId].via);return atlasDigestText(zoneId)+(near?"\nOn the region: "+near:"");}
};
function atlasBriefCut(text,cap){
  var at;
  if(text.length<=cap)return text;
  at=Math.max(text.lastIndexOf(". ",cap),text.lastIndexOf(".\n",cap),text.lastIndexOf("; ",cap));
  return text.slice(0,at>0?at+1:cap).replace(/\s+$/,"")+ATLAS_BRIEF_CUT;
}
function atlasMapBlock(){
  var A=atlasLive(),p=A?atlasPointer():null,where,zone,sheet;
  if(!A)return "";
  try{
    if(!p||A.ptr!==JSON.stringify([p.world,p.sub])){
      /* the pointer moved outside a turn and nothing followed it: say nothing rather than describe the old place */
      if(typeof console!=="undefined")console.warn("[atlas] the MAP block is withheld this turn — the atlas has not followed the story's current place");
      return ATLAS_BRIEF_HEAD+"\nThe map has not followed the story to its current place yet; it says nothing this turn.\n\n";
    }
    where=atlasWhere();
    /* a party that has left the mapped places is not served the sheet it left */
    zone=(where.placed&&!(A.off&&!A.off.within))?A.at:A.seed;
    sheet=(ATLAS_BRIEF[A.zones[zone].kind]||function(B,z){return atlasDigestText(z);})(A,zone);
    return ATLAS_BRIEF_HEAD+"\n"+where.text+"\n"+atlasBriefCut(sheet,ATLAS_BRIEF_CAP)+"\n"+ATLAS_BRIEF_RULE+"\n\n";
  }catch(e){
    /* said once per campaign per session: this runs for every prompt, and a standing failure must not toast and mail a report per turn */
    if(atlasOnce(A,"brief"))atlasProblem("telling the GM what the map says",e);
    else if(typeof console!=="undefined")console.warn("[atlas] the MAP block failed again \u2014 "+((e&&e.message)?e.message:e));
    return ATLAS_BRIEF_HEAD+"\nThe map could not be read this turn; it says nothing.\n\n";
  }
}

/* ── load ──────────────────────────────────────────────────────────────────────────────────────────────────── */
function atlasShapeProblem(A){
  var ids,i,r,z,n;
  if(!A||typeof A!=="object")return "it is not an object";
  if(typeof A.v!=="number")return "it has no version";
  if(A.v>ATLAS_VER)return null;/* a newer build's store: atlasLive leaves it alone */
  if(typeof A.seed!=="string"||!A.seed)return "it has no seed";
  if(!A.zones||typeof A.zones!=="object")return "it has no zones";
  if(!A.zones[A.seed]||A.zones[A.seed].kind!=="region"||A.zones[A.seed].parent||!A.zones[A.seed].params||A.zones[A.seed].params.seed!==A.seed)return "its region recipe is missing or does not carry the campaign seed";
  ids=Object.keys(A.zones);
  for(i=0;i<ids.length;i++){
    r=A.zones[ids[i]];
    if(!r||typeof r!=="object"||typeof r.kind!=="string")return "zone '"+ids[i]+"' is malformed";
    if(ids[i]!==A.seed&&(!r.parent||!A.zones[r.parent]))return "zone '"+ids[i]+"' hangs from a zone that is not there";
  }
  /* every zone hangs from the region: a chain that loops would make every reader walk in circles */
  for(i=0;i<ids.length;i++){z=ids[i];n=0;while(z!==A.seed){z=A.zones[z].parent;if(!z||!A.zones[z]||++n>64)return "zone '"+ids[i]+"' does not hang from the region";}}
  return null;
}
/* WRITE, at every load door: migrate the store's shape, set an unreadable store aside as evidence (never repaired by
   guessing, never silently dropped), drop ties and a position that point at zones that are gone. Returns true on a change. */
function atlasHeal(){
  var A=(typeof worldState!=="undefined"&&worldState)?worldState.atlas:null,why,changed=false,keys,i;
  if(A===undefined||A===null)return false;
  while(A&&typeof A==="object"&&typeof A.v==="number"&&A.v<ATLAS_VER){
    if(!ATLAS_MIGRATIONS[A.v]){worldState.atlasJunk={why:"no migration from atlas v"+A.v,was:A,turn:atlasTurn()};delete worldState.atlas;atlasSay("warn","this campaign's map is from an older shape this build cannot lift (v"+A.v+") — it was set aside");return true;}
    A=worldState.atlas=ATLAS_MIGRATIONS[A.v](A);changed=true;
  }
  why=atlasShapeProblem(A);
  if(why){worldState.atlasJunk={why:why,was:A,turn:atlasTurn()};delete worldState.atlas;atlasSay("warn","this campaign's map could not be read ("+why+") — it was set aside, the story is untouched");return true;}
  if(A.v>ATLAS_VER)return changed;
  if(!A.names||typeof A.names!=="object"){A.names=keyedDict();changed=true;}
  keys=Object.keys(A.names);
  for(i=0;i<keys.length;i++)if(!A.names[keys[i]]||!A.zones[A.names[keys[i]].zone]){delete A.names[keys[i]];changed=true;atlasSay("info","dropped the tie for '"+keys[i]+"' — its zone is not in the atlas");}
  if(A.at&&!A.zones[A.at]){A.at=null;A.spot=null;A.ptr=null;changed=true;atlasSay("warn","the party's place on the map pointed at a zone that is not there — the map will follow the story again");}
  return changed;
}
